  startNewSessionConfirm: { en: "Starting a new 3-month session moves every student back to the Waiting List so you can re-place them for the new term. This can't be undone. Continue?", ht: "Kòmanse yon nouvo sesyon 3 mwa ap voye tout elèv retounen nan Lis Datant pou ou ka replase yo pou nouvo tèm nan. Sa pa ka anile. Kontinye?", es: "Iniciar una nueva sesión de 3 meses devuelve a todos los estudiantes a la Lista de Espera para que pueda reubicarlos en el nuevo período. Esto no se puede deshacer. ¿Continuar?", fr: "Démarrer une nouvelle session de 3 mois renvoie tous les étudiants dans la Liste d'Attente afin de les replacer pour le nouveau trimestre. Ceci est irréversible. Continuer ?" },
  newSessionStarted: { en: "New session started. All students moved to the Waiting List.", ht: "Nouvo sesyon kòmanse. Tout elèv yo deplase nan Lis Datant.", es: "Nueva sesión iniciada. Todos los estudiantes movidos a la Lista de Espera.", fr: "Nouvelle session démarrée. Tous les étudiants ont été déplacés vers la Liste d'Attente." },
  downloadTemplate: { en: "Download Template", ht: "Telechaje Modèl", es: "Descargar Plantilla", fr: "Télécharger le Modèle" },
  uploadStudents: { en: "Upload Student List", ht: "Telechaje Lis Elèv", es: "Cargar Lista de Estudiantes", fr: "Importer une Liste d'Étudiants" },
  uploadStudentsDesc: { en: "Download the template below, fill in one row per student (First Name, Last Name, Phone, Email, Street Address, City, ZIP Code), then upload it here. State is always Rhode Island, so there's no column for it. New students are added to the Waiting List and each is enrolled with a unique ID (NB-#####).", ht: "Telechaje modèl anba a, ranpli yon liy pou chak elèv (Prenon, Non Fanmi, Telefòn, Imèl, Ri, Vil, Kòd Postal), epi telechaje l isit la. Eta a se toujou Rhode Island, kidonk pa gen kolòn pou li. Nouvo elèv yo ajoute nan Lis Datant epi yo resevwa yon ID inik (NB-#####).", es: "Descargue la plantilla a continuación, complete una fila por estudiante (Nombre, Apellido, Teléfono, Correo, Calle, Ciudad, Código Postal), y luego súbala aquí. El Estado siempre es Rhode Island, así que no hay columna para eso. Los nuevos estudiantes se agregan a la Lista de Espera y reciben un ID único (NB-#####).", fr: "Téléchargez le modèle ci-dessous, remplissez une ligne par étudiant (Prénom, Nom, Téléphone, E-mail, Rue, Ville, Code Postal), puis importez-le ici. L'État est toujours Rhode Island, donc il n'y a pas de colonne pour cela. Les nouveaux étudiants sont ajoutés à la Liste d'Attente et reçoivent un identifiant unique (NB-#####)." },
  importBtn: { en: "Import", ht: "Enpòte", es: "Importar", fr: "Importer" },
  chooseFileFirst: { en: "Please choose a file first.", ht: "Tanpri chwazi yon fichye dabò.", es: "Por favor elija un archivo primero.", fr: "Veuillez d'abord choisir un fichier." },
  importError: { en: "Couldn't read that file. Please use the downloaded template (.xlsx or .csv).", ht: "Nou pa t kapab li fichye sa a. Tanpri itilize modèl ou telechaje a (.xlsx oswa .csv).", es: "No se pudo leer ese archivo. Por favor use la plantilla descargada (.xlsx o .csv).", fr: "Impossible de lire ce fichier. Veuillez utiliser le modèle téléchargé (.xlsx ou .csv)." },
  studentsImported: { en: "student(s) added to the Waiting List.", ht: "elèv ajoute nan Lis Datant.", es: "estudiante(s) agregados a la Lista de Espera.", fr: "étudiant(s) ajouté(s) à la Liste d'Attente." },
  dragHint: { en: "Drag a name into a classroom, or use the dropdown on each card (easier on tablets).", ht: "Trennen yon non nan yon klasrom, oswa itilize meni an sou chak kat (pi fasil sou tablèt).", es: "Arrastre un nombre a un aula, o use el menú desplegable en cada tarjeta (más fácil en tabletas).", fr: "Faites glisser un nom dans une salle de classe, ou utilisez le menu déroulant sur chaque carte (plus facile sur tablette)." },
