  classFullMessage: { en: "This class is full (12 students). Move someone out first, or add them to the waiting list.", ht: "Klas sa a plen (12 elèv). Retire yon moun anvan, oswa mete yo nan lis datant.", es: "Esta clase está llena (12 estudiantes). Retire a alguien primero, o agréguelo a la lista de espera.", fr: "Cette classe est complète (12 élèves). Retirez d'abord quelqu'un, ou ajoutez-le à la liste d'attente." },
  removeStudentConfirm: { en: "Remove this student from the roster entirely?", ht: "Retire elèv sa a nèt nan lis la?", es: "¿Eliminar completamente a este estudiante de la lista?", fr: "Supprimer complètement cet étudiant de la liste ?" },
  manageRosterHere: { en: "Add, remove, and place students on the Students page.", ht: "Ajoute, retire, epi plase elèv sou paj Elèv la.", es: "Agregue, elimine y ubique estudiantes en la página de Estudiantes.", fr: "Ajoutez, supprimez et placez les étudiants sur la page Étudiants." },
