  noDaysMeansOnline: { en: "Leave all days unchecked for an online/remote classroom with no fixed in-person schedule.", ht: "Kite tout jou yo san mache pou yon klasrom anliy san orè fiks an pèsòn.", es: "Deje todos los días sin marcar para un aula en línea sin horario fijo presencial.", fr: "Ne cochez aucun jour pour une salle en ligne sans horaire fixe en personne." },
  addClassroom: { en: "Add Classroom", ht: "Ajoute Klasrom", es: "Agregar Aula", fr: "Ajouter la Salle" },
  deleteClassroomConfirm: { en: "Remove this classroom? Students placed in it will move back to the Waiting List.", ht: "Retire klasrom sa a? Elèv ki nan li yo ap retounen nan Lis Datant.", es: "¿Eliminar esta aula? Los estudiantes en ella volverán a la Lista de Espera.", fr: "Supprimer cette salle ? Les étudiants qui s'y trouvent retourneront dans la Liste d'Attente." },
