  waitingListNote: { en: "Students here are ready to be placed — either into a class already in progress, or into whatever the next 3-month session turns out to be.", ht: "Elèv ki isit la pare pou plase — swa nan yon klas ki deja kòmanse, oswa nan nenpòt pwochen sesyon 3 mwa a.", es: "Los estudiantes aquí están listos para ser ubicados, ya sea en una clase en curso o en la próxima sesión de 3 meses.", fr: "Les étudiants ici sont prêts à être placés — soit dans un cours déjà en cours, soit dans la prochaine session de 3 mois." },
  importPastRosterTitle: { en: "Upload a Past Session's Roster", ht: "Telechaje Lis Elèv yon Sesyon Pase", es: "Cargar la Lista de una Sesión Pasada", fr: "Importer la Liste d'une Session Passée" },
  importPastRosterDesc: { en: "For record-keeping only — this does not touch the current Waiting List or active classrooms. Download the template, fill in one row per student (First Name, Last Name, Phone, Email, Street Address, City, ZIP Code, Classroom — State is always Rhode Island), pick which past session it belongs to, then upload it.", ht: "Se sèlman pou dosye — sa a pa afekte Lis Datant aktyèl la oswa klasrom aktif yo. Telechaje modèl la, ranpli yon liy pou chak elèv (Prenon, Non Fanmi, Telefòn, Imèl, Ri, Vil, Kòd Postal, Klasrom — Eta a se toujou Rhode Island), chwazi ki sesyon pase li ye, epi telechaje l.", es: "Solo para fines de registro — esto no afecta la Lista de Espera actual ni las aulas activas. Descargue la plantilla, complete una fila por estudiante (Nombre, Apellido, Teléfono, Correo, Calle, Ciudad, Código Postal, Aula — el Estado siempre es Rhode Island), elija a qué sesión pasada pertenece y luego súbala.", fr: "À des fins d'archivage uniquement — cela n'affecte pas la Liste d'Attente actuelle ni les salles de classe actives. Téléchargez le modèle, remplissez une ligne par étudiant (Prénom, Nom, Téléphone, E-mail, Rue, Ville, Code Postal, Salle de classe — l'État est toujours Rhode Island), choisissez à quelle session passée cela appartient, puis importez-le." },
  selectSession: { en: "Select a past session", ht: "Chwazi yon sesyon pase", es: "Seleccione una sesión pasada", fr: "Sélectionnez une session passée" },
  addPastSessionFirst: { en: "Add a past session above before uploading a roster for it.", ht: "Ajoute yon sesyon pase anwo a anvan ou telechaje yon lis pou li.", es: "Agregue una sesión pasada arriba antes de cargar una lista para ella.", fr: "Ajoutez une session passée ci-dessus avant d'y importer une liste." },
  pastStudentsImported: { en: "student(s) added to that past session's roster.", ht: "elèv ajoute nan lis sesyon pase sa a.", es: "estudiante(s) agregados a la lista de esa sesión pasada.", fr: "étudiant(s) ajouté(s) à la liste de cette session passée." },
