  noPastRosterYet: { en: "No students uploaded for this session yet.", ht: "Poko gen elèv telechaje pou sesyon sa a.", es: "Aún no se han cargado estudiantes para esta sesión.", fr: "Aucun étudiant importé pour cette session pour l'instant." },
